import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.BIas3y6W.js";const g=JSON.parse('{"title":"Game in an Hour — Game menu","description":"","frontmatter":{"source":"weeks/03-prompting-and-save-points/game-menu.md"},"headers":[],"relativePath":"weeks/03-prompting-and-save-points/game-menu.md","filePath":"weeks/03-prompting-and-save-points/game-menu.md"}'),d={name:"weeks/03-prompting-and-save-points/game-menu.md"};function s(n,t,i,h,l,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="game-in-an-hour--game-menu" tabindex="-1">Game in an Hour — Game menu <a class="header-anchor" href="#game-in-an-hour--game-menu" aria-label="Permalink to &quot;Game in an Hour — Game menu&quot;">​</a></h1><p>Pick <strong>one</strong> game for Game in an Hour (week 3, Studio B). You keep working on it in week 4, when you break it and restore it, compare two AI models on its next change, and write an automated test for one of its functions. Each entry has a difficulty rating, why it makes a good first game, what tends to go wrong, and a <strong>sample 5-step plan</strong> with a &quot;done when&quot; check for every step.</p><p>Use the sample plan to <strong>check and edit</strong> the plan your AI proposes, not to replace it. Asking for a plan and then improving it is the Plan step of the <a href="./../../resources/safe-loop.html">Safe Loop</a>.</p><p><strong>Difficulty:</strong> ★ Easy (good if you&#39;re new to JavaScript or the web) · ★★ Medium · ★★★ Hard (if you&#39;re comfortable with JavaScript, or as homework).</p><h2 id="rules-for-every-game" tabindex="-1">Rules for every game <a class="header-anchor" href="#rules-for-every-game" aria-label="Permalink to &quot;Rules for every game&quot;">​</a></h2><ul><li>One file, <code>game/index.html</code>, with the CSS and JavaScript inside it.</li><li>No libraries and no external images, sounds or fonts. Use emoji, colored shapes or the HTML <code>&lt;canvas&gt;</code> element (a drawing area on the page; not the same thing as Gemini&#39;s Canvas feature).</li><li>Playable on a laptop with a keyboard or mouse. Touch controls are one of the homework feature ideas.</li><li>Each step adds <strong>one</strong> visible feature you can test in under a minute.</li><li>Use a generic name for games based on famous ones (&quot;Flappy-style&quot;, not the original&#39;s name), and draw your own simple shapes rather than copying someone else&#39;s art.</li></ul><h2 id="quick-pick" tabindex="-1">Quick pick <a class="header-anchor" href="#quick-pick" aria-label="Permalink to &quot;Quick pick&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Game</th><th>Difficulty</th><th>Controls</th><th>Pick it if you…</th></tr></thead><tbody><tr><td>1</td><td><a href="#1-reaction-timer">Reaction timer</a></td><td>★ Easy</td><td>Mouse</td><td>want a guaranteed win</td></tr><tr><td>2</td><td><a href="#2-whack-a-mole">Whack-a-mole</a></td><td>★ Easy</td><td>Mouse</td><td>like fast, simple games</td></tr><tr><td>3</td><td><a href="#3-memory-match">Memory match</a></td><td>★ Easy</td><td>Mouse</td><td>like puzzles more than action</td></tr><tr><td>4</td><td><a href="#4-typing-speed-test">Typing speed test</a></td><td>★ Easy</td><td>Keyboard</td><td>want something useful</td></tr><tr><td>5</td><td><a href="#5-simon-says">Simon says</a></td><td>★★ Medium</td><td>Mouse or keys</td><td>like patterns and sequences</td></tr><tr><td>6</td><td><a href="#6-snake">Snake</a></td><td>★★ Medium</td><td>Arrow keys</td><td>want a classic</td></tr><tr><td>7</td><td><a href="#7-pong">Pong</a></td><td>★★ Medium</td><td>Mouse or keys</td><td>like smooth movement</td></tr><tr><td>8</td><td><a href="#8-flappy-style">Flappy-style</a></td><td>★★ Medium</td><td>Space or click</td><td>want a one-button game</td></tr><tr><td>9</td><td><a href="#9-breakout">Breakout</a></td><td>★★★ Hard</td><td>Mouse or keys</td><td>finished Pong fast and want more</td></tr><tr><td>10</td><td><a href="#10-2048">2048</a></td><td>★★★ Hard</td><td>Arrow keys</td><td>like logic puzzles and tricky rules</td></tr></tbody></table><p><strong>Your own idea?</strong> Fine, if your instructor agrees and it fits the rules above in five small steps. Write your own plan in the same format.</p><hr><h2 id="1-reaction-timer" tabindex="-1">1. Reaction timer <a class="header-anchor" href="#1-reaction-timer" aria-label="Permalink to &quot;1. Reaction timer&quot;">​</a></h2><p><strong>Difficulty:</strong> ★ Easy</p><p>Wait for the screen to turn green, then click as fast as you can.</p><ul><li><strong>Why it&#39;s a good first game:</strong> no animation loop and no collisions, just a timer and clicks. You&#39;ll get to step 5.</li><li><strong>Watch out for:</strong> clicking &quot;too early&quot; while waiting; the random delay must be different every round.</li></ul><table tabindex="0"><thead><tr><th>Step</th><th>Build</th><th>Done when</th></tr></thead><tbody><tr><td>1</td><td>Layout: a title, a large colored panel with the text &quot;Click to start&quot;, and an empty results area</td><td>The page shows all three; clicking does nothing yet</td></tr><tr><td>2</td><td>Waiting: clicking the panel turns it red with &quot;Wait for green…&quot;, then after a random 1–4 seconds it turns green with &quot;Click!&quot;</td><td>Over three tries, the wait is noticeably different each time</td></tr><tr><td>3</td><td>Measure: clicking the green panel shows your reaction time in milliseconds; clicking again starts a new round</td><td>A time appears after each green click, and the next round starts cleanly</td></tr><tr><td>4</td><td>Too soon: clicking while it&#39;s red shows &quot;Too soon!&quot; and cancels the round</td><td>An early click never shows a time and never turns the panel green afterwards</td></tr><tr><td>5</td><td>Best of five: record five valid attempts, then show the average and best time, with a &quot;Play again&quot; button</td><td>After five attempts the average and best appear; &quot;Play again&quot; clears them</td></tr></tbody></table><h2 id="2-whack-a-mole" tabindex="-1">2. Whack-a-mole <a class="header-anchor" href="#2-whack-a-mole" aria-label="Permalink to &quot;2. Whack-a-mole&quot;">​</a></h2><p><strong>Difficulty:</strong> ★ Easy</p><p>Moles pop up in a 3×3 grid of holes. Click them before they vanish.</p><ul><li><strong>Why it&#39;s a good first game:</strong> a grid, random choice, a score and a timer are the building blocks of many games.</li><li><strong>Watch out for:</strong> two moles showing at once; the score counting clicks on empty holes; timers that keep running after the game ends.</li></ul><table tabindex="0"><thead><tr><th>Step</th><th>Build</th><th>Done when</th></tr></thead><tbody><tr><td>1</td><td>Layout: a 3×3 grid of holes, &quot;Score: 0&quot;, &quot;Time: 30&quot; and a Start button</td><td>Everything shows; nothing moves</td></tr><tr><td>2</td><td>After Start, a mole (emoji) appears in a random hole about once a second</td><td>The mole jumps between random holes, never two at once</td></tr><tr><td>3</td><td>Clicking the mole adds 1 to the score and hides it; clicking an empty hole does nothing</td><td>The score goes up only for hits</td></tr><tr><td>4</td><td>A 30-second countdown; at 0 the moles stop and &quot;Final score: N&quot; appears</td><td>The timer reaches 0 and the board freezes</td></tr><tr><td>5</td><td>Moles stay up for less time as the game goes on; &quot;Play again&quot; resets score and timer</td><td>Late moles vanish noticeably faster; a new game starts at 0 and 30</td></tr></tbody></table><h2 id="3-memory-match" tabindex="-1">3. Memory match <a class="header-anchor" href="#3-memory-match" aria-label="Permalink to &quot;3. Memory match&quot;">​</a></h2><p><strong>Difficulty:</strong> ★ Easy</p><p>Flip cards two at a time to find matching pairs.</p><ul><li><strong>Why it&#39;s a good first game:</strong> no timing pressure while you build it, and the rules are easy to test.</li><li><strong>Watch out for:</strong> clicking a third card while two are showing; clicking the same card twice counting as a match.</li></ul><table tabindex="0"><thead><tr><th>Step</th><th>Build</th><th>Done when</th></tr></thead><tbody><tr><td>1</td><td>A 4×4 grid of face-down cards, holding 8 emoji pairs in shuffled order</td><td>16 cards show; reloading changes the order (ask for a temporary &quot;show all&quot; button to check, then remove it)</td></tr><tr><td>2</td><td>Clicking a card flips it to show its emoji</td><td>Cards flip face up when clicked</td></tr><tr><td>3</td><td>Two matching cards stay face up; two different cards flip back after 1 second; no clicks count during that second</td><td>Matches stay, misses flip back, a third click is ignored</td></tr><tr><td>4</td><td>A move counter, and &quot;You won in N moves!&quot; when all pairs are found</td><td>The counter goes up once per pair of flips; the message appears at the end</td></tr><tr><td>5</td><td>A timer and a &quot;New game&quot; button that reshuffles</td><td>The timer stops on a win; &quot;New game&quot; gives a fresh shuffled board</td></tr></tbody></table><h2 id="4-typing-speed-test" tabindex="-1">4. Typing speed test <a class="header-anchor" href="#4-typing-speed-test" aria-label="Permalink to &quot;4. Typing speed test&quot;">​</a></h2><p><strong>Difficulty:</strong> ★ Easy</p><p>Type a sentence as fast and accurately as you can; see your words per minute.</p><ul><li><strong>Why it&#39;s a good first game:</strong> text boxes and keyboard events, no graphics. Easy to check the math yourself.</li><li><strong>Watch out for:</strong> the timer starting on page load instead of the first keystroke; words per minute calculated wrongly.</li></ul><table tabindex="0"><thead><tr><th>Step</th><th>Build</th><th>Done when</th></tr></thead><tbody><tr><td>1</td><td>Layout: a sentence to copy, a text box, and a results area</td><td>All three show; typing in the box works but nothing is measured</td></tr><tr><td>2</td><td>The timer starts on the first keystroke and stops when you press Enter; show the seconds taken</td><td>The time shown matches a phone stopwatch within about a second</td></tr><tr><td>3</td><td>Show words per minute (characters typed ÷ 5, per minute) and accuracy (% of characters that match)</td><td>Typing a 50-character sentence perfectly in 30 seconds shows 20 WPM and 100%</td></tr><tr><td>4</td><td>Live feedback: each typed character turns green if correct, red if wrong</td><td>Mistakes are highlighted as you type</td></tr><tr><td>5</td><td>A random sentence from a list of 10, a &quot;Try again&quot; button, and the best WPM so far this session</td><td>Each try gets a new sentence; the best score updates only when beaten</td></tr></tbody></table><h2 id="5-simon-says" tabindex="-1">5. Simon says <a class="header-anchor" href="#5-simon-says" aria-label="Permalink to &quot;5. Simon says&quot;">​</a></h2><p><strong>Difficulty:</strong> ★★ Medium</p><p>Four colored pads light up in a sequence; repeat it. Each round adds one more.</p><ul><li><strong>Why it&#39;s a good first game:</strong> a growing array (JavaScript&#39;s version of a list) and taking turns between the computer and the player.</li><li><strong>Watch out for:</strong> the player clicking during the computer&#39;s playback; a pad lighting twice in a row looking like one flash.</li></ul><table tabindex="0"><thead><tr><th>Step</th><th>Build</th><th>Done when</th></tr></thead><tbody><tr><td>1</td><td>Four colored pads in a 2×2 grid, a Start button and &quot;Level: 0&quot;; clicking a pad makes it flash</td><td>Each pad flashes brighter for a moment when clicked</td></tr><tr><td>2</td><td>After Start, the computer plays a sequence that grows by one random pad each round</td><td>Level 3 plays three flashes, with clear gaps, even if the same pad repeats</td></tr><tr><td>3</td><td>The player repeats the sequence; right moves to the next level, wrong shows &quot;Game over: you reached level N&quot;</td><td>A correct repeat advances; one wrong click ends the game</td></tr><tr><td>4</td><td>Clicks during the computer&#39;s playback are ignored; playback speeds up every 5 levels</td><td>Clicking during playback does nothing; level 6 plays faster than level 1</td></tr><tr><td>5</td><td>Keyboard controls (keys 1–4) and a &quot;Play again&quot; button; show the best level this session</td><td>The game can be played without a mouse; the best level updates</td></tr></tbody></table><h2 id="6-snake" tabindex="-1">6. Snake <a class="header-anchor" href="#6-snake" aria-label="Permalink to &quot;6. Snake&quot;">​</a></h2><p><strong>Difficulty:</strong> ★★ Medium</p><p>Steer a growing snake to eat food without hitting the walls or yourself.</p><ul><li><strong>Why it&#39;s a good first game:</strong> the classic. It introduces a <em>game loop</em> (code that updates and redraws the screen many times a second) on a simple grid.</li><li><strong>Watch out for:</strong> reversing into yourself (pressing Left while moving Right); food appearing inside the snake; arrow keys scrolling the page.</li></ul><table tabindex="0"><thead><tr><th>Step</th><th>Build</th><th>Done when</th></tr></thead><tbody><tr><td>1</td><td>A <code>&lt;canvas&gt;</code> with a 20×20 grid, a 3-cell snake in the middle and one food square</td><td>Snake and food are drawn; nothing moves</td></tr><tr><td>2</td><td>The snake moves one cell about every 150 ms; arrow keys change direction but can&#39;t reverse it; arrow keys don&#39;t scroll the page</td><td>The snake moves and turns; pressing the opposite direction is ignored</td></tr><tr><td>3</td><td>Eating food makes the snake one cell longer, adds 1 to the score, and moves the food to a random empty cell</td><td>Length and score go up; food never appears on the snake</td></tr><tr><td>4</td><td>Hitting a wall or itself ends the game: &quot;Game over. Score: N. Press Space to restart&quot;</td><td>Both kinds of crash end the game; Space starts a new one</td></tr><tr><td>5</td><td>The snake speeds up every 5 foods; show the best score this session</td><td>Speed visibly increases; the best score survives a restart (not a reload)</td></tr></tbody></table><h2 id="7-pong" tabindex="-1">7. Pong <a class="header-anchor" href="#7-pong" aria-label="Permalink to &quot;7. Pong&quot;">​</a></h2><p><strong>Difficulty:</strong> ★★ Medium</p><p>Keep the ball in play against a computer paddle. First to 5 wins.</p><ul><li><strong>Why it&#39;s a good first game:</strong> smooth movement, bouncing and collisions, the core of most action games.</li><li><strong>Watch out for:</strong> the ball getting stuck inside a paddle; a computer player that never misses.</li></ul><table tabindex="0"><thead><tr><th>Step</th><th>Build</th><th>Done when</th></tr></thead><tbody><tr><td>1</td><td>A <code>&lt;canvas&gt;</code> with two paddles, a ball, a dashed center line and &quot;0 – 0&quot;</td><td>Everything is drawn; nothing moves</td></tr><tr><td>2</td><td>The ball moves in a game loop and bounces off the top and bottom edges</td><td>The ball moves smoothly and keeps bouncing</td></tr><tr><td>3</td><td>The left paddle follows the mouse (or W/S keys); the ball bounces off both paddles</td><td>Hitting returns the ball; missing lets it pass</td></tr><tr><td>4</td><td>Scoring: a ball past a paddle gives the other side a point and restarts from the center; the right paddle follows the ball at a limited speed</td><td>Both sides can score; the computer can be beaten</td></tr><tr><td>5</td><td>First to 5 wins with a message; P pauses; Space restarts</td><td>The winner is announced; pause and restart work</td></tr></tbody></table><h2 id="8-flappy-style" tabindex="-1">8. Flappy-style <a class="header-anchor" href="#8-flappy-style" aria-label="Permalink to &quot;8. Flappy-style&quot;">​</a></h2><p><strong>Difficulty:</strong> ★★ Medium</p><p>One button makes your bird flap up through gaps in scrolling pipes.</p><ul><li><strong>Why it&#39;s a good first game:</strong> gravity in two lines of code, and a single control that works for everyone.</li><li><strong>Watch out for:</strong> the bird flying off the top; pipes with impossible gaps; the game being far too hard at first.</li></ul><table tabindex="0"><thead><tr><th>Step</th><th>Build</th><th>Done when</th></tr></thead><tbody><tr><td>1</td><td>A <code>&lt;canvas&gt;</code> with a sky, a ground strip, a bird (circle or emoji) and &quot;Press Space to start&quot;</td><td>Everything is drawn; nothing moves</td></tr><tr><td>2</td><td>Gravity: after Space, the bird falls; Space or a click makes it jump; it can&#39;t leave the top of the screen</td><td>The bird falls, jumps and stays on screen</td></tr><tr><td>3</td><td>Pairs of pipes with a gap scroll from right to left; a new pair every 1.5 seconds; the gap&#39;s height is random</td><td>Pipes keep coming, each gap at a different height, always passable</td></tr><tr><td>4</td><td>Touching a pipe or the ground ends the game; passing a pipe adds 1 to the score</td><td>Crashes end the game; the score counts pipes passed</td></tr><tr><td>5</td><td>A game-over screen with the score and best this session; Space restarts; tune gravity and gap size until a beginner can score 5</td><td>A classmate can score 5 on their first or second try</td></tr></tbody></table><h2 id="9-breakout" tabindex="-1">9. Breakout <a class="header-anchor" href="#9-breakout" aria-label="Permalink to &quot;9. Breakout&quot;">​</a></h2><p><strong>Difficulty:</strong> ★★★ Hard</p><p>Bounce a ball off your paddle to smash rows of bricks.</p><ul><li><strong>Why it&#39;s harder:</strong> many objects to collide with, and angles that depend on where the ball hits the paddle.</li><li><strong>Watch out for:</strong> the ball passing through bricks when it moves fast; hitting two bricks at once.</li></ul><table tabindex="0"><thead><tr><th>Step</th><th>Build</th><th>Done when</th></tr></thead><tbody><tr><td>1</td><td>A <code>&lt;canvas&gt;</code> with a paddle at the bottom, a ball and 5 rows × 8 bricks</td><td>Everything is drawn; nothing moves</td></tr><tr><td>2</td><td>The ball moves and bounces off the walls and ceiling; the paddle moves with the mouse or arrow keys; a ball past the bottom resets</td><td>The ball bounces; the paddle moves; a missed ball restarts</td></tr><tr><td>3</td><td>The ball bounces off the paddle, at an angle that depends on where it hits</td><td>Hitting the paddle&#39;s edge sends the ball more sideways than hitting the middle</td></tr><tr><td>4</td><td>A ball hitting a brick removes it, bounces, and adds 10 points</td><td>Bricks disappear one at a time; the score goes up by 10</td></tr><tr><td>5</td><td>Three lives, &quot;You win!&quot; when all bricks are gone, Space to restart</td><td>Losing three balls ends the game; clearing the board wins</td></tr></tbody></table><h2 id="10-2048" tabindex="-1">10. 2048 <a class="header-anchor" href="#10-2048" aria-label="Permalink to &quot;10. 2048&quot;">​</a></h2><p><strong>Difficulty:</strong> ★★★ Hard</p><p>Slide numbered tiles on a 4×4 grid; equal tiles merge. Reach 2048.</p><ul><li><strong>Why it&#39;s harder:</strong> the merge rules have tricky edge cases, which makes it a great lesson in testing, and a hard one to finish in an hour.</li><li><strong>Watch out for:</strong> a tile merging twice in one move (<code>2 2 4</code> sliding left should give <code>4 4</code>, not <code>8</code>); new tiles appearing after a move that changed nothing.</li></ul><table tabindex="0"><thead><tr><th>Step</th><th>Build</th><th>Done when</th></tr></thead><tbody><tr><td>1</td><td>A 4×4 grid drawn from a list of numbers, starting with two random tiles (2 or 4) and &quot;Score: 0&quot;</td><td>Two tiles show; reloading gives different starting tiles</td></tr><tr><td>2</td><td>The Left arrow slides all tiles left without merging; a new tile appears only if something moved</td><td>Tiles slide left; pressing Left again when nothing can move adds no tile</td></tr><tr><td>3</td><td>Merging on Left: equal neighbors merge once per move and add their total to the score</td><td><code>2 2 2 2</code> becomes <code>4 4</code>; <code>2 2 4</code> becomes <code>4 4</code>; the score goes up by the merged values</td></tr><tr><td>4</td><td>Right, Up and Down work the same way</td><td>All four arrows slide and merge correctly</td></tr><tr><td>5</td><td>&quot;You win!&quot; at 2048 (with a &quot;keep going&quot; option), &quot;Game over&quot; when no move is possible, and a &quot;New game&quot; button</td><td>Both messages appear at the right time; New game resets the board and score</td></tr></tbody></table><hr><h2 id="ways-to-break-it-on-purpose" tabindex="-1">Ways to break it on purpose <a class="header-anchor" href="#ways-to-break-it-on-purpose" aria-label="Permalink to &quot;Ways to break it on purpose&quot;">​</a></h2><p>In week 4, Studio A (<a href="./../04-undo-compare-explain/lab.html">lab Part A1</a>), you break your game on purpose, commit the broken version, and then restore the last working one. Pick one:</p><ul><li><strong>Accept a vague, unreviewed change.</strong> Send <code>Make the game much more exciting. Change whatever you like.</code>, paste the result without testing, and commit it.</li><li><strong>Delete a line by hand.</strong> In the <code>&lt;script&gt;</code> section, delete a line containing <code>}</code> or a line that starts with <code>if</code>, and commit.</li><li><strong>Change a number to something silly.</strong> Set a speed to <code>1000</code> or a grid size to <code>2</code>, and commit.</li></ul><p>Then follow the week 4 lab to go back. The restore itself needs no AI. Being able to undo a bad change calmly is the point of the exercise.</p>',65)])])}const p=e(d,[["render",s]]);export{g as __pageData,p as default};
